CREATE FUNCTION public.owner_launch_upload(_task uuid,_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t client_tasks; BEGIN SELECT * INTO t FROM client_tasks WHERE id=_task FOR UPDATE; IF t.id IS NULL OR t.client_id IS DISTINCT FROM my_client_id() OR NOT has_role(auth.uid(),'client') OR t.owner_action_kind NOT IN('input','upload') THEN RAISE EXCEPTION 'This task does not request your upload'; END IF; IF task_gate_a_locked(t.id) THEN RAISE EXCEPTION 'Locked: waiting for Gate A'; END IF; IF _path NOT LIKE t.client_id::text||'/owner-input/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='client-files' AND name=_path) THEN RAISE EXCEPTION 'Upload a file for this hotel first'; END IF; UPDATE client_tasks SET evidence_url=_path,status='in_progress' WHERE id=t.id; INSERT INTO task_activity(task_id,user_id,action,note) VALUES(t.id,auth.uid(),'owner_upload',_path); END $$;
REVOKE ALL ON FUNCTION public.owner_launch_upload(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owner_launch_upload(uuid,text) TO authenticated;
CREATE FUNCTION public.gate_write_integrity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE final_code text; BEGIN
IF TG_OP='INSERT' THEN IF NEW.status='signed' AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Create an unsigned gate, then use Sign gate'; END IF; RETURN NEW; END IF;
IF NEW.gate_code IS DISTINCT FROM OLD.gate_code OR NEW.launch_id IS DISTINCT FROM OLD.launch_id OR NEW.client_id IS DISTINCT FROM OLD.client_id THEN RAISE EXCEPTION 'Gate identity cannot be changed'; END IF;
IF NEW.approval_method IS DISTINCT FROM OLD.approval_method AND NEW.status<>'signed' AND NEW.client_approved_at IS NOT DISTINCT FROM OLD.client_approved_at THEN RAISE EXCEPTION 'Approval method is recorded by the approval action'; END IF;
IF NEW.status='signed' AND OLD.status<>'signed' THEN
SELECT p.final_gate_code INTO final_code FROM client_launches l JOIN plans p ON p.id=l.plan_id WHERE l.id=NEW.launch_id;
IF NEW.gate_code=final_code AND coalesce(trim(NEW.approval_file_path),'')='' AND NEW.client_approved_at IS NULL THEN RAISE EXCEPTION 'Upload the hotel approval file or ask the owner to Approve in North Star'; END IF;
IF OLD.status<>'ready' THEN RAISE EXCEPTION 'Gate is not ready'; END IF;
END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.gate_write_integrity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER b_gate_write_integrity BEFORE INSERT OR UPDATE ON public.client_gates FOR EACH ROW EXECUTE FUNCTION public.gate_write_integrity();
DO $ddl$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.get_my_launch()'::regprocedure) INTO d; d:=replace(d,'''status'', l.status','''status'',CASE WHEN l.no_launch_checklist AND l.status=''active'' THEN ''live'' ELSE l.status END'); d:=regexp_replace(d,'''modules'', \(SELECT jsonb_agg[\s\S]*?LEFT JOIN launch_phases ph ON ph.code = x.phase_code\)\)','''modules'',''[]''::jsonb)'); EXECUTE d; END $ddl$;